  "flexi.fold": "Сгиб вверх и вниз до",
  "flexi.helpFold": "Тело разрезается поперёк длины на полосы, и в каждом разрезе появляется шарнир, который печатается сразу на месте, так что после печати полосы сгибаются вверх и вниз, как флекси-брелок. Сначала положите тело плашмя на стол; там, где будут шарниры, оно должно быть не меньше примерно 5 мм в высоту и 15–20 мм в ширину.",
  "flexi.autoSize": "Размер шарнира по телу",
