  "lid.screwInHint": "Тело получает внутри отверстия резьбу глубиной {depth} мм, крышка — такую же на пробке под пластиной, которая уходит вниз на {height} мм. Где хватает места, пробка — кольцо со стенкой {wall} мм. Боковые стороны витков наклонены под 45°, поэтому обе детали печатаются без поддержек.",
