  "status.punchTooMany": "Контур {punch} содержит больше {count} линий и кривых, слишком много для эскиза. Сначала упростите пуансон.",
  "status.punchChanged": "Сцена изменилась во время пробивки; выполните команду ещё раз",
  "editor.tool.offset": "Смещение",
  "offset.title": "Сместить тело",
  "offset.subtitle": "Каждая грань сдвинута на одно расстояние",
  "offset.help": "Увеличивает или уменьшает тело вдоль его граней. Для зазора посадки: увеличьте его и оставьте как отверстие.",
  "offset.direction": "Направление",
