  "paint.mode.fillHint": "Щелчок заливает грань до её острых рёбер: плоскую грань, круглую стенку, внутреннюю сторону отверстия.",
  "paint.mode.circleHint": "Щелчок кладёт на поверхность круглое пятно заданного диаметра.",
