  "status.paintTooMany": "На этом теле {count} мазков — больше нельзя. «Снять всё» позволяет начать заново.",
  "paint.wholeFaces": "Эта сетка не замкнута: круги и лассо следуют её треугольникам.",
  "status.honeycombConverted": "Сотовая структура преобразована в массив отверстий: {count}",
  "welcome.moreHolePatternTitle": "Массив отверстий",
  "welcome.moreHolePatternBody": "Щёлкните по плоской грани тела и распределите по ней отверстия: круглые, квадратные, прямоугольные, шестигранные или щелевидные, сеткой или в шахматном порядке, с шагом, отступом от края и глубиной (сквозные или заданной глубины). Предпросмотр показывает отверстия до их создания; они остаются обычными отверстиями, сгруппированными с телом — для вентиляции, решёток динамиков, корзинок и корпусов. Или расставьте венец отверстий под винты вдоль края, по одному в каждом углу, при желании с цековкой или зенковкой. Так же повторяется и своя форма — заклёпки или рифлёный лист. На круглой стенке цилиндра или трубы отверстия идут по всему кругу, каждое направлено к оси.",
  "welcome.moreSupportRibTitle": "Опорное ребро",
  "welcome.moreSupportRibBody": "Печатайте деталь наклонно на ребре без поддержек слайсера: щёлкните по её нижней грани, и под ней с небольшим зазором встанет тонкое ребро на овальной опоре, с крошечными мостиками ровно в один слой, которые держат деталь и потом отламываются.",
  "welcome.moreStencilBridgesTitle": "Перемычки трафарета",
  "welcome.moreStencilBridgesBody": "Печатайте трафарет с прорезанным насквозь текстом: середина букв вроде o, a и b получает маленькие перемычки к пластине нужной ширины и высоты, и ничего не выпадает.",
  "welcome.moreFaceTitle": "Выдавить грань",
  "welcome.moreFaceBody": "выдвиньте плоскую грань тела наружу или вырежьте в ней карман, с отступом от края, скруглёнными углами и глубиной, с предпросмотром - и на импортированных STL.",
  "welcome.moreTextureTitle": "Текстура поверхности",
  "welcome.moreTextureBody": "наносит рельеф на любое тело — для хвата или для красоты: накатка, канавки, соты, древесная текстура, канат, картинка как карта высот или текст, вокруг круглых тел или плоско вдоль оси. До шести узоров на одном теле, каждый на своих гранях. Для печати в два цвета узор может стать и отдельной деталью собственного цвета.",
  "welcome.moreVaseTitle": "Вазы и горшки",
  "welcome.moreVaseBody": "отдельная фигура для ваз, горшков и абажуров: форма корпуса, сечение, закрутка, узоры, дренажные отверстия, поддон и крышка — сплошная для режима вазы в слайсере или полая. Крышка как у чайника — это верх самой вазы, и узор продолжается через стык.",
  "welcome.moreOffsetTitle": "Смещение и вырезание",
  "welcome.moreOffsetBody": "увеличивает или уменьшает точное тело на заданное расстояние, со всех сторон или только вбок, — для зазора посадки с натягом — или за один шаг вырезает одну деталь из другой с зазором по всему контуру.",
  "welcome.morePunchTitle": "Пробивка",
  "welcome.morePunchBody": "вырезает контур одного тела насквозь через другое, где бы оно ни стояло перед ним: силуэт чайника сквозь табличку, логотип сквозь крышку. Сдвиньте или поверните пуансон и пробейте снова; зазор пропустит напечатанную деталь.",
  "welcome.moreClearanceTitle": "Проверить зазор",
  "welcome.moreClearanceBody": "перед печатью деталей, которые должны двигаться, - шарнира, напечатанного на месте, флекси-игрушки, крышки в коробке - находит пары, которые пересекаются, касаются или стоят ближе заданного зазора.",
  "guide.select.holePattern": "Массив отверстий (кнопка на ленте рядом с «Массив», правый щелчок по телу или Ctrl+K): щёлкните по плоской грани или круглой стенке, затем задайте форму, размер, шаг, порядок, отступ и глубину отверстий. Отверстия отображаются в предпросмотре; «Создать» добавляет их как отверстия, сгруппированные с телом. Разгруппировка снова отделяет их.",
  "guide.select.faceTool": "Грань (кнопка на ленте рядом с «Массив отверстий», правый щелчок по телу или Ctrl+K): щёлкните по плоской грани, выберите «Наружу» или «Внутрь», затем задайте отступ от края, радиус углов и глубину. Добавляется тело из эскиза, сгруппированное с телом.",
  "guide.select.supportRib": "Опорное ребро (кнопка на ленте, правый щелчок по телу или Ctrl+K): щёлкните по нижней грани детали, напечатанной наклонно на ребре. Тонкое ребро встаёт под ней с небольшим зазором, на овальной опоре, и держится за деталь маленькими мостиками высотой в один слой; задайте сопло и слои вашего слайсера.",
  "scalePercent.errorTooSmall": "«{name}» станет меньше 0,01 мм.",
  "scalePercent.errorTooLarge": "«{name}» станет больше, чем допускает её форма. Задайте больший «Лимит пользовательского размера» в разделе «Параметры фигур по умолчанию» в настройках или выберите меньший процент.",
  "status.scaledByPercent": "Масштабировано до {percent} %",
