  "status.meshTooDense": "В этой сетке {triangles} треугольников. Обработка кромок выдерживает {limit}; сверх этого ядро считает дольше, чем разумно ждать. Для фигуры из списка фигур пока используйте её собственные настройки. Импортированную деталь загрузите как STEP или сначала сохраните с меньшим числом треугольников.",
  "status.meshDenseAsk": "В этой сетке {triangles} треугольников — больше, чем {limit}, на которые рассчитана обработка рёбер. Дальше это может занять много минут, страница может зависнуть, а всё несохранённое пропадёт, если её придётся закрыть. Сначала сохраните проект.\n\nВсё равно попробовать?",
  "status.threadTooDense": "Резьба строится из {triangles} треугольников — слишком много для обработки кромок, которая останавливается на {limit}. Поэтому добавляйте резьбу после обработки кромок: сначала фаска или скругление тела, потом резьба. Фаска головки в свойствах сразу обрабатывает кромку головки винта — без этого обходного пути.",
  "status.vaseTooDense": "В этой вазе {triangles} треугольников — больше, чем {limit}, с которыми справляются выдалбливание и обработка кромок. Ваза сама становится полой и имеет свою крышку: в разделе «Исполнение» выбери «Полая со стенкой», а крышку — на карточке «Принадлежности».",
  "status.unlockImageDelete": "Снимите блокировку с изображения эскиза клавишей L, прежде чем удалять его",
  "status.unlockImageEdit": "Снимите блокировку с изображения эскиза клавишей L, прежде чем изменять его",
  "status.updatingRevolve": "Обновление предпросмотра вращения…",
  "status.waitForPreview": "Дождитесь подходящего предпросмотра кромки, прежде чем применять",
