  "status.cutTooComplex": "Геометрия слишком сложна для разделения: {triangles} треугольников, лимит — {limit}. Сначала упростите полигональную сетку или увеличьте лимит в настройках рабочей области.",
  "status.groupNotMerged": "Сгруппировано, но не объединено в одно тело: вместе у частей {triangles} треугольников, больше лимита {limit}. При экспорте они остаются наложенными друг на друга, и слайсеры сообщают об этом как об ошибках (non-manifold рёбра). Увеличьте лимит в настройках рабочей области или упростите сетку, затем сгруппируйте снова.",
  "status.cutNotWatertightTooComplex": "Эта полигональная сетка не герметична, и при {triangles} треугольниках она слишком сложна для резервного разделения (лимит {limit}). Сначала восстановите или упростите сетку.",
