  "thread.flankAngleHint": "Угол между двумя боковыми сторонами зуба. 60° — острая V-резьба, 30° — трапецеидальная. Если угол не больше 90°, наклон боковых сторон к горизонтали — не меньше 45°, поэтому резьба печатается без поддержек.",
