  "thread.axialClearanceHint": "Дополнительный люфт вдоль оси резьбы, мм, сверх зазора: каждый зуб гайки становится тоньше на эту величину, диаметр остаётся прежним. Для свободно вращающейся резьбы без бокового люфта: оставьте зазор 0,2–0,3 и установите здесь 0,2. При 0 люфт обеспечивается только зазором, который раскрывает боковые стороны примерно вдвое меньше.",
  "thread.clearanceHint": "Дополнительный зазор по всему диаметру. Для печатной резьбы нужно больше, чем кажется: зазор между боковыми сторонами составляет примерно половину этой величины. 0,3 — туго, 0,4 — обычно, 0,5 — свободно. Сначала распечатайте тестовую пару.",
  "thread.boltClearanceHint": "Уменьшает диаметр болта на эту величину — для металлической гайки без собственного люфта (0,3–0,4, как у печатной гайки). С печатной гайкой оставьте 0 и задайте зазор в самой гайке.",
