  "screwBoss.screwOption": "{size} – отверстие {hole} мм",
  "screwBoss.insertHint": "Отверстие на миллиметр глубже вставки. Напечатанные отверстия выходят чуть меньше нарисованных: сначала напечатайте одну бобышку на пробу и поправьте отверстие на одну-две десятых.",
