  "snapFit.bothHint": "Оба стоят там, где будут после защёлкивания, крышка сверху: основание крючка под крышку, спинку упора к внутренней стороне стенки корпуса, затем «Разделить на части» разделит их.",
  "snapFit.hookHint": "Только крючок — для окна в стенке или своего упора.",
