  "snapFit.strainFine": "При защёлкивании растягивается у основания на {strain} %: годится для PLA (примерно до 2 %).",
  "snapFit.strainTough": "Растягивается у основания на {strain} %: много для PLA, годится для PETG или ABS (примерно до 4 %). Более длинная или тонкая лапка гнётся мягче.",
  "snapFit.strainTooMuch": "Растягивается у основания на {strain} %: сломается. Удлините или утоньшите лапку или уменьшите зацеп.",
