  "prop.ribFootThickness": "Толщина подошвы",
  "rib.footHint": "Тонкая пластина под всем ребром, ребро посередине (у косынки — под стороной, лежащей на дне). Она держит ребро на столе принтера или на дне, так что стоит и более тонкое ребро.",
  "rib.footThicknessHint": "Несколько слоёв: 0,8 мм — это четыре слоя по 0,2 мм.",
  "prop.ribFootShape": "Форма подошвы",
  "rib.footSquare": "Прямоугольная",
  "rib.footOval": "Овальная",
  "rib.footShapeHint": "У овальной подошвы нет углов, которые могут оторваться от стола, когда пластик остывает. Она выходит за концы ребра ровно настолько, чтобы и они стояли на ней: форма становится длиннее, а ребро сохраняет свою длину.",
  "prop.hingeLength": "Длина (ось)",
