  "gridfinity.compartmentsHint": "Перегородки заканчиваются на высоте полок для этикеток, не мешая контейнеру сверху; каждый отсек остаётся шириной не менее 6 мм.",
  "gridfinity.compartmentsTrayHint": "В лотке перегородки доходят до верха; каждый отсек остаётся шириной не менее 6 мм.",
