  "inspector.surfaceCrackSeed": "Начальное значение",
  "inspector.surfaceCrackSeedHint": "То же начальное значение — те же трещины, другое разыгрывает их заново. Длина считается в % высоты, от края к центру — в % радиуса.",
  "inspector.surfaceCrackGold": "Золотое заполнение отдельной деталью",
  "inspector.surfaceCrackRecess": "Золото утоплено",
  "inspector.surfaceCrackGoldHint": "Заполнение трещин становится отдельной деталью золотого цвета, для второго филамента; его верх лежит на такой глубине под поверхностью. Для этого узор действует внутрь.",
  "inspector.surfacePatternPart": "Узор отдельной деталью",
  "inspector.surfacePatternColor": "Цвет узора",
  "inspector.surfacePatternRaisedHint": "То, что выступает из тела, становится отдельной деталью этого цвета, для второго филамента; тело остаётся прежним. Обе детали лежат вместе в связке: они перемещаются вместе, а текстуру по-прежнему можно изменить или снять.",
  "inspector.surfacePatternCutHint": "То, что вырезано в теле, становится отдельной деталью этого цвета, которая заполняет углубление до поверхности, для второго филамента. Обе детали лежат вместе в связке: они перемещаются вместе, а текстуру по-прежнему можно изменить или снять.",
  "inspector.surfacePatternWayHint": "Только для узора наружу или внутрь, в одну сторону на каждом слое: при текущих настройках узор остаётся единым с телом.",
  "status.surfaceNoCracks": "Ни одна трещина не нашла пути по этому телу. Попробуйте другое начало («Где угодно» подходит для любого тела), более длинные трещины или пустите узор на больше граней.",
  "status.surfaceCracks": "Линий трещин: {count}, вместе {length} мм.",
  "status.surfaceGold": "Золотое заполнение лежит в трещинах отдельной деталью.",
  "status.surfacePatternRaised": "Узор стал отдельной деталью в связке с прежним телом.",
  "status.surfacePatternCut": "Углубление заполняет отдельная деталь в связке с телом.",
  "status.surfacePatternOneBody": "Узор остаётся единым с телом: отдельной деталью он может быть, только если идёт наружу или внутрь, в одну сторону на каждом слое.",
  "surfaceTexture.text": "Надпись (наклеенная)",
  "inspector.surfaceTextContent": "Текст",
  "inspector.surfaceTextSize": "Размер букв",
  "inspector.surfaceTextAround": "По кругу (°)",
  "inspector.surfaceTextHeight": "Высота (%)",
  "inspector.surfaceTextTurn": "Поворот (°)",
  "inspector.surfaceTextHint": "Надпись прилегает, как прижатая этикетка: по кругу 0° — спереди, 90° — справа; если ось лежит на X или Y, 0° — сверху. Высота считается в % вдоль оси; размер букв — высота заглавной буквы.",
