  "surfaceTexture.carbonTwill22Hint": "Каждая лента проходит над двумя поперечными и под двумя: ровная диагональ большинства карбоновых деталей.",
  "surfaceTexture.carbonTwill21Hint": "Над двумя, под одной: вертикальные ленты видны длинными, поперечные — короткими.",
  "surfaceTexture.carbonTwill31Hint": "Над тремя, под одной: длинные вертикальные ленты, поперечные лишь короткими участками между ними.",
  "inspector.surfaceCarbonCross": "Ширина поперечных лент",
  "inspector.surfaceCarbonHint": "Поперечные ленты 0: такой же ширины, как вертикальные. Шире или уже — неравномерное плетение. Вокруг тела ширина ленты немного округляется, чтобы плетение замкнулось.",
  "inspector.surfaceSeed": "Расположение",
  "inspector.surfaceSeedHint": "Другое число расставит ячейки или зёрна заново.",
  "inspector.surfaceImage": "Изображение",
  "inspector.surfaceImageLoad": "Загрузить своё изображение…",
  "inspector.surfaceImageHint": "Светлое получает полную глубину, тёмное остаётся как есть. Тёмный рисунок на прозрачном фоне, например чёрные линии в SVG, считается по своим линиям: они получают полную глубину. Своё изображение хранится в проекте в оттенках серого, не больше 256 точек на сторону; плитка такой ширины, как задано, и такой высоты, как к ней подходит изображение.",
  "inspector.surfaceTileHeight": "Высота плитки (0 = как у изображения)",
  "inspector.surfaceImageHeight": "Высота изображения",
  "inspector.surfaceImageOnceHint": "Изображение наносится один раз, как наклейка: «По кругу» и «Высота» задают его середину, как у надписи. Вне его поверхность остаётся гладкой; «Глубина» и «Направление» задают, насколько оно выступает или вдавлено. Высота изображения 0 сохраняет его пропорции. Если выбраны грани, изображение всегда ложится на них.",
  "inspector.surfaceImageTurn": "Повёрнуто (°)",
  "inspector.surfaceImageInvert": "Поменять светлое и тёмное",
  "inspector.surfaceImageBlur": "Размыть",
  "inspector.surfaceImageTiling": "Плитки",
  "inspector.surfaceGrainHint": "Зернистость лежит в пространстве, а не проецируется: без шва и без растяжения, одинаковая на любой форме.",
