  "vaseCheck.conflictLamp": "абажур",
  "vaseCheck.watertightHollow": "Водонепроницаемо: стенка и дно не меньше {mm} мм; в слайсере не меньше трёх линий стенки и пяти слоёв дна, лучше немного больше потока или температуры. Сначала проверьте водой над раковиной.",
  "vaseCheck.watertightVaseMode": "Водонепроницаемо в режиме вазы: более широкая линия (около 0,6–0,8 мм при сопле 0,4 мм) и немного более высокая температура делают единственную стенку плотной; рёбра внутри или двойная стенка делают её прочнее. Сначала проверьте водой над раковиной.",
