  "vaseCheck.lampStanding": "Настольный: закрепите патрон кольцом абажура в отверстии дна (Ø {mm} мм), кабель идёт через полую ножку. Выберите ножку такой высоты, чтобы корпус патрона поместился под ней, — измерьте.",
