  "export.stl.description": "Сетка для 3D-печати",
  "export.stl.note": "Лучше всего подходит для слайсеров и 3D-печати. Геометрия экспортируется как триангулированная сетка. В Chrome и Edge вы один раз выбираете папку и имя файла; последующие экспорты STL этого проекта записываются в тот же файл, если только вы не введёте другое имя: тогда вас спросят снова.",
  "export.stlLinkedFile": "Сохраняется в {name}",
